const { DatabaseSync } = require('node:sqlite');
const db = new DatabaseSync('/workspace/world.db');

const emailId = 'ethan.it.specialist/RE: High Priority: Onboarding Equipment Setup Needed.eml';
const content = \`Hello Olivia,

Thank you for letting me know. I've received your onboarding request and have scheduled time tomorrow morning to complete the setup for the new contractor.

Here's what I'll have ready before start of business tomorrow (September 21):

1. Standard Windows laptop — configured and ready to go
2. VPN access — set up and tested
3. Email account — created and configured

Please let me know if there are any additional requirements or specific software the contractor will need.

Best regards,
Ethan\`;

const stmt = db.prepare(\`
  INSERT INTO ob_emails (email_id, username, from_address, to_address, subject, content, inbox_owner)
  VALUES (?, ?, ?, ?, ?, ?, ?)
\`);

stmt.run(
  emailId,
  'ethan.it.specialist',
  'ethan.it.specialist@company.com',
  'olivia.hr.manager@company.com',
  'RE: High Priority: Onboarding Equipment Setup Needed',
  content,
  'olivia.hr.manager'
);

